const svcCard = (s, sizes = '(min-width: 1100px) 31vw, (min-width: 600px) 48vw, 100vw') => `<a class="svc-card" href="${s.slug}.html" data-reveal="up"><div class="svc-media">${img(s.image, { sizes, alt: '' })}<span class="svc-icon">${icon(s.icon)}</span></div><div class="svc-body"><p class="svc-label">${esc(s.label)}</p><h3>${esc(s.name)}</h3><p class="svc-text">${esc(s.card)}</p><ul class="chips">${s.tags.map(t => `<li>${esc(t)}</li>`).join('')}</ul><span class="svc-go">Explore ${esc(s.name.toLowerCase())}${icon('i-arrow')}</span></div></a>`;
