const number = value => new Intl.NumberFormat('en-US').format(value);
const price = value => 'USD ' + number(value);
const carTitle = car => `${car.year} ${car.make} ${car.model}`;
const carFuel = value => ({ 'Hybrid(Petrol)': 'Petrol hybrid', 'Hybrid(Diesel)': 'Diesel hybrid' }[value] || value);
const carTransmission = value => ({ AT: 'Automatic', MT: 'Manual' }[value] || value);
function carCatalogue() {
  const cars = vehiclePriceGuide.vehicles;
  const makes = [...new Set(cars.map(car => car.make))].sort();
  const years = [...new Set(cars.map(car => car.year))].sort((a, b) => b - a);
  const checked = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(vehiclePriceGuide.checkedOn + 'T00:00:00Z'));
  const cards = cars.map(car => {
    const title = carTitle(car);
    const enquiry = 'enquire.html?service=vehicle&type=' + encodeURIComponent(title + ' (BE FORWARD ' + car.sourceRef + ')');
    const specs = [
      ['Mileage', number(car.mileageKm) + ' km'],
      ['Engine', car.engineCc ? number(car.engineCc) + ' cc' : 'See source'],
      ['Transmission', carTransmission(car.transmission)],
      ['Fuel', carFuel(car.fuel)],
    ];
    const search = [car.title, title, carFuel(car.fuel), car.sourceRef].join(' ');
    return `<article class="car-card" data-car data-make="${esc(car.make)}" data-price="${car.priceUsd}" data-year="${car.year}" data-mileage="${car.mileageKm}" data-search="${esc(search)}"><div class="car-card-top"><span class="car-mark">${icon('i-vehicle')}</span><span class="car-origin"><span>${esc(car.country)}</span><span>Right-hand drive</span></span></div><h3 tabindex="-1">${esc(title)}</h3><p class="car-price">${price(car.priceUsd)}<span>FOB vehicle price only</span></p><dl class="car-specs">${specs.map(([label, value]) => `<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p class="car-source-ref">BE FORWARD reference ${esc(car.sourceRef)}</p><div class="car-actions">${link('Ask about this model', enquiry)}<a class="car-source" data-price-source href="${esc(car.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="View exporter listing and photos for ${esc(title)}, reference ${esc(car.sourceRef)}">View source &amp; photos${icon('i-arrow', 'link-icon')}</a></div></article>`;
  }).join('');
  return { tone: 'paper', id: 'car-catalogue', cls: 'car-catalogue', label: 'car-catalogue-title', inner: `<div class="wrap" data-car-catalogue><div class="car-intro"><div>${kicker('Explore the import market', 'i-vehicle')}<h2 id="car-catalogue-title">Cars &amp; import prices.</h2><p>Start with a model and a budget. Compare researched exporter listings, then talk to Spear Line about the vehicle and destination you have in mind.</p></div><div class="car-summary"><strong>${number(cars.length)}</strong><span>priced examples across ${makes.length} makes</span><span>Researched <time datetime="${vehiclePriceGuide.checkedOn}">${checked}</time></span></div></div><div class="car-price-note"><strong>Vehicle-only prices in USD.</strong><p>Freight, insurance, taxes, clearing and delivery are additional. These are external listing examples, not confirmed Spear Line stock. Prices and availability can change; ask for a quote for your destination.</p><a data-price-source href="${esc(vehiclePriceGuide.termsUrl)}" target="_blank" rel="noopener noreferrer">How the exporter defines FOB prices${icon('i-arrow', 'link-icon')}</a></div><form class="car-controls" data-car-controls hidden role="search" aria-label="Find an import vehicle"><div class="car-fields"><label class="car-search">Search models<input type="search" name="search" data-car-search placeholder="Try RAV4, Hilux or hybrid" autocomplete="off"></label><label>Make<select name="make" data-car-make><option value="">All makes</option>${makes.map(make => `<option value="${esc(make)}">${esc(make)}</option>`).join('')}</select></label><label>Budget up to (USD)<input type="number" name="budget" data-car-budget min="0" step="100" inputmode="numeric" placeholder="Any budget"></label><label>Year from<select name="year" data-car-year><option value="0">Any year</option>${years.map(year => `<option value="${year}">${year}</option>`).join('')}</select></label><label>Sort by<select name="sort" data-car-sort><option value="price-asc">Lowest price</option><option value="price-desc">Highest price</option><option value="year-desc">Newest year</option><option value="mileage-asc">Lowest mileage</option></select></label></div><div class="car-tools"><p data-car-count role="status" aria-live="polite" aria-atomic="true">${cars.length} examples</p><button type="reset" class="car-reset">Reset filters</button></div></form><div class="car-grid" data-car-grid>${cards}</div><div class="car-empty" data-car-empty hidden><h3>No matching vehicles.</h3><p>Try a different model, a higher vehicle budget or an earlier year. You can also ask us to research your requirement.</p></div><div class="car-more"><button class="btn btn-secondary" type="button" data-car-more hidden>Show more cars</button></div><div class="car-enquiry"><div><h3>Looking for something specific?</h3><p>Share your preferred model, year, vehicle budget and destination. We will discuss the next step and the full import costs with you.</p></div>${btn('Start a vehicle enquiry', 'enquire.html?service=vehicle')}</div></div>` };
}

function servicePage(s) {
  const others = services.filter(o => o.id !== s.id);
  const listings = s.id === 'vehicle' && inventory.length ? `<div class="listings" data-stagger>${inventory.map(v => `<article class="card listing glass" data-tilt><div class="listing-media">${img(v.image || 'vehicles-suv', { sizes: '(min-width: 1100px) 30vw, 100vw', alt: v.title })}</div><div class="listing-body">${v.status ? `<span class="listing-status">${esc(v.status)}</span>` : ''}<h3>${esc(v.title)}</h3><p class="listing-meta">${[v.year, ...(v.details || [])].filter(Boolean).map(esc).join(', ')}</p>${v.price ? `<p class="listing-price">${esc(v.price)}</p>` : ''}${link('Ask about this vehicle', 'enquire.html?service=vehicle&type=' + encodeURIComponent(v.title))}</div></article>`).join('')}</div>` : '';
  const list = [
    { tone: 'navy', cls: 'hero page-hero', field: true, inner: pageHero({ image: s.image, crumb: s.name, kickerText: s.label, kickerIcon: s.icon, title: s.hero.title, lede: s.hero.lede, actions: s.id === 'vehicle' ? btn('Browse cars & prices', '#car-catalogue') + btn(s.cta, 'enquire.html?service=vehicle', { variant: 'glass', iconId: 'i-chat' }) : btn(s.cta, 'enquire.html?service=' + s.id) + btn('How it works', 'how-it-works.html', { variant: 'glass', iconId: 'i-route' }) }) },
    ...(s.id === 'vehicle' ? [carCatalogue()] : []),
    { tone: 'paper', cls: 'features', inner: `<div class="wrap">${s.items.map((item, i) => `<article class="feature${i % 2 ? ' feature-flip' : ''}"><div class="feature-media" data-reveal="clip"><div class="pan ${i % 2 ? 'pan-b' : 'pan-a'}">${img(item.image, { sizes: '(min-width: 1100px) 50vw, 100vw' })}</div></div><div class="feature-copy" data-reveal="up"><span class="feature-index">${icon(s.icon)}</span><h2 data-split>${esc(item.title)}</h2><p>${esc(item.text)}</p>${link('Discuss your requirement', 'enquire.html?service=' + s.id + (item.type ? '&type=' + encodeURIComponent(item.type) : ''))}</div></article>`).join('')}</div>` },
    ...(s.id === 'vehicle' && inventory.length ? [{ tone: 'sand', cls: 'listings-section', label: 'listings-title', inner: `<div class="wrap">${head('Available vehicles', 'Ask about any listing and we will confirm the details for your enquiry.').replace('<h2 data-split>', '<h2 id="listings-title" data-split>') + listings}</div>` }] : []),
    { tone: 'ocean', cls: 'brief-section', label: 'brief-title', backdrop: s.backdrop, glow: true, inner: `<div class="wrap brief-grid"><div class="brief-card glass" data-reveal="up" data-tilt><h2 id="brief-title" data-split>${esc(s.briefTitle)}</h2><p>${esc(s.brief)}</p><ul class="check-list">${s.include.map(item => `<li>${icon('i-check')}<span>${esc(item)}</span></li>`).join('')}</ul>${btn(s.cta, 'enquire.html?service=' + s.id)}</div><div class="brief-note" data-reveal="up"><div class="brief-photo pan pan-b">${img(s.moment, { sizes: '(min-width: 1100px) 40vw, 100vw' })}</div><p class="note-big">Availability, specifications, price and arrangements are confirmed for your individual enquiry.</p>${link('Read the questions people ask', 'faq.html')}</div></div>` },
    ...[strip(s.id)].filter(Boolean),
    { tone: 'sand', cls: 'cross', label: 'cross-title', inner: `<div class="wrap">${head('One line, three services.', 'Many requirements touch more than one. Start with any of them.').replace('<h2 data-split>', '<h2 id="cross-title" data-split>')}<div class="cross-grid">${others.map(o => svcCard(o, '(min-width: 1100px) 50vw, 100vw')).join('')}</div></div>` },
    closing(s.closing)
  ];
  return layout(s.id, s.label, s.card, list);
}

/* ---------- How it works ---------- */
const bring = services.map(s => ({ s, list: s.include }));
const processPage = [
  { tone: 'navy', cls: 'hero page-hero', field: true, inner: pageHero({ image: 'sourcing-detail', crumb: 'How it works', kickerText: 'A clear way forward', kickerIcon: 'i-route', title: 'From a brief to your next move.', lede: 'Four steps, what to bring for each service, and what an enquiry is and is not.', actions: btn('Start an enquiry', 'enquire.html') }) },
  { tone: 'paper', cls: 'timeline-section', label: 'steps-title', inner: `<div class="wrap">${head('Simple beginnings. Clear next steps.', 'An enquiry is the start of a conversation, not a booking or a purchase.').replace('<h2 data-split>', '<h2 id="steps-title" data-split>')}<ol class="timeline" data-timeline><span class="timeline-line" aria-hidden="true"><span data-timeline-fill></span></span>${steps.map((s, i) => `<li class="timeline-step" data-timeline-step><span class="timeline-node" aria-hidden="true">${icon(s.icon)}</span><div class="timeline-card glass"><span class="step-num">${String(i + 1).padStart(2, '0')}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div></li>`).join('')}</ol></div>` },
  { tone: 'ocean', cls: 'bring-section', label: 'bring-title', backdrop: 'warehouse', glow: true, inner: `<div class="wrap">${head('What to bring.', 'The more precise the brief, the better the first conversation. You can always add details later.').replace('<h2 data-split>', '<h2 id="bring-title" data-split>')}<div class="bring-grid" data-stagger>${bring.map(({ s, list }) => `<article class="card bring-card glass" data-tilt><span class="card-icon">${icon(s.icon)}</span><p class="card-label">${esc(s.name)}</p><h3>${esc(s.label)}</h3><ul class="check-list">${list.map(item => `<li>${icon('i-check')}<span>${esc(item)}</span></li>`).join('')}</ul>${link(s.cta, 'enquire.html?service=' + s.id)}</article>`).join('')}</div><p class="fine" data-reveal>Always include your name and a phone number or email address. Please leave out identity documents, card details and bank details.</p></div>` },
  closing()
];

/* ---------- FAQ ---------- */
const answer = a => a === null ? `<span data-faq-closed>${esc(onlineAnswer.closed)}</span><span data-faq-open hidden>${esc(onlineAnswer.open)}</span>` : esc(a);
const faqPage = [
  { tone: 'navy', cls: 'hero page-hero', field: true, inner: pageHero({ image: 'warehouse', crumb: 'Questions', kickerText: 'Good to know', kickerIcon: 'i-chat', title: 'Questions, answered plainly.', lede: 'Enquiries, privacy, imagery and how Spear Line works.' }) },
  { tone: 'paper', cls: 'faq-section', inner: `<div class="wrap faq-layout"><aside class="faq-side" aria-label="Find a question"><div class="faq-search"><label for="faq-filter">Search questions</label><div class="search-field">${icon('i-search')}<input id="faq-filter" type="search" placeholder="Type a word, like price" autocomplete="off" data-faq-filter></div><p class="faq-empty" data-faq-empty hidden>No questions match that word. Try another, or start an enquiry.</p></div><nav class="faq-index" aria-label="Question topics" data-faq-index><ul>${faq.map((g, i) => `<li><a href="#faq-${i}">${esc(g.group)}</a></li>`).join('')}</ul></nav></aside><div class="faq-groups">${faq.map((g, i) => `<section class="faq-group" id="faq-${i}" aria-labelledby="faq-${i}-title"><h2 id="faq-${i}-title" data-reveal>${esc(g.group)}</h2><div class="faq-list" data-accordion>${g.items.map((item, j) => `<details${i === 0 && j === 0 ? ' open' : ''}><summary><span>${esc(item.q)}</span><span class="plus" aria-hidden="true"></span></summary><div class="answer"><p>${answer(item.a)}</p></div></details>`).join('')}</div></section>`).join('')}</div></div>` },
  closing()
];
const faqLd = faq.flatMap(g => g.items).filter(i => i.a !== null).map(i => ({ '@type': 'Question', name: i.q, acceptedAnswer: { '@type': 'Answer', text: i.a } }));

/* ---------- Contact ---------- */
